function initEquipment(root=document){
 const $=id=>Eam.find(root,id),value=id=>$(id)?.value||"",put=(id,v)=>{const el=$(id);if(el)el.textContent=v;};
 if(!$('equipment-list'))return;
 const treeExpanded=new Map();let treeMode='location';
 const s=Eam.s,can=Eam.can(['engineer','supervisor']),label={draft:'草稿',active:'在用',stopped:'停用',pending_scrap:'待报废',scrapped:'已报废'},fields=['code','name','model','location','ownerId','criticality','manufacturer','serial','commissionedAt'];
 let page=1,editing=null,structureId=null,partId=null,incompleteOnly=false;
 const STATE_KEY='eam-ledger-state-v1'+(root.dataset?.instance?'-'+root.dataset.instance:'');
 const text=(tag,value)=>{const n=document.createElement(tag);n.textContent=value;if(tag==='small')n.className='d-block text-body-secondary small mt-1 text-nowrap';return n;};
 const cell=(label,...nodes)=>{const td=document.createElement('td');td.dataset.label=label;td.className='px-3 py-3 text-nowrap';const limits={'设备名称 / 编码':200,'位置 / 型号':200,'制造商':160,'责任人':100};for(const node of nodes){if(node.nodeType===1){node.classList.add('text-nowrap');if(limits[label]){node.classList.add('d-block','text-truncate');node.style.maxWidth=limits[label]+'px';node.title=node.textContent;}}}td.append(...nodes);return td;};
 const button=(text,callback,enabled=true)=>{const b=document.createElement('button');b.type='button';b.className='btn btn-outline-secondary btn-sm text-nowrap';b.textContent=text;b.disabled=!enabled;b.onclick=callback;return b;};
 const confirmRun=(title,action,p)=>Eam.confirm(title,reason=>{if(!Eam.run(action,{...p,reason}))return false;render();return true;});
 const healthOf=e=>e.id==='EQ-001'?EamDomain.health(s):'未知';
 const incomplete=e=>e.lifecycle==='draft'||!e.manufacturer||!e.serial||!e.commissionedAt;
 const open=(record,readonly=false)=>{editing=record;for(const key of fields)$('eq-'+key).value=record?.[key]||({ownerId:'P05',criticality:'normal'}[key]||'');$('eq-reason').value='';$('equipment-form').querySelectorAll('input,select').forEach(el=>el.disabled=readonly);$('equipment-save').hidden=readonly;put('equipment-form-title',record?(readonly?'查看设备':'编辑设备'):'新增设备草稿');put('equipment-form-status',record?label[record.lifecycle]+' / 资料版本 '+record.revision:'新增后为草稿，验收合格再启用');put('equipment-form-error','');$('equipment-dialog').showModal();};
 const baseCols=[{key:'name',label:'设备名称 / 编码'},{key:'location',label:'位置 / 型号'},{key:'lifecycle',label:'生命周期'},{key:'health',label:'健康'},{key:'owner',label:'责任人'}];
 const optCols=[
   {key:'criticality',label:'重要等级',get:e=>e.criticality==='critical'?'关键':'一般'},
   {key:'manufacturer',label:'制造商',get:e=>e.manufacturer||'—'},
   {key:'commissionedAt',label:'投运日期',get:e=>e.commissionedAt||'—'}
 ];
 const colOn={criticality:true,manufacturer:true,commissionedAt:true};
 const cellFor=(key,e)=>{switch(key){
   case 'name':return [text('strong',e.name),text('small',e.code)];
   case 'location':return [text('span',e.location),text('small',e.model)];
   case 'lifecycle':{const n=text('span',label[e.lifecycle]);n.className='badge '+({active:'text-bg-success',draft:'text-bg-secondary',stopped:'text-bg-secondary',pending_scrap:'text-bg-warning',scrapped:'text-bg-secondary'}[e.lifecycle]||'text-bg-secondary');return [n];}
   case 'health':{const n=text('span',healthOf(e));n.className='badge '+(healthOf(e)==='故障'?'text-bg-danger':healthOf(e)==='正常'?'text-bg-success':'text-bg-secondary');return [n];}
   case 'owner':return [text('span',EamDomain.personName(e.ownerId))];
   default:{const c=optCols.find(x=>x.key===key),n=text('span',c.get(e));if(key!=='manufacturer')n.className='text-nowrap';return [n];}
 }};
 function saveState(){try{sessionStorage.setItem(STATE_KEY,JSON.stringify({search:value('search'),life:value('filter-life'),health:value('filter-health'),criticality:value('filter-criticality'),manufacturer:value('filter-manufacturer'),page,incompleteOnly}));}catch{}}
 function loadState(){try{const st=JSON.parse(sessionStorage.getItem(STATE_KEY)||'{}');if(typeof st.search==='string')$('search').value=st.search;if(st.life)$('filter-life').value=st.life;if(st.health)$('filter-health').value=st.health;if(st.criticality)$('filter-criticality').value=st.criticality;if(st.manufacturer)$('filter-manufacturer').value=st.manufacturer;if(st.incompleteOnly)incompleteOnly=!!st.incompleteOnly;if(Number.isInteger(st.page))page=st.page;}catch{}}
 function isStatActive(dim){const life=value('filter-life');return (dim==='all'&&!life&&!incompleteOnly)||(dim==='active'&&life==='active')||(dim==='scrap'&&life==='pending_scrap')||(dim==='incomplete'&&incompleteOnly);}
 function renderStats(){const all=s.equipmentRecords;const cards=[['总数',all.length,'all'],['在役',all.filter(e=>e.lifecycle==='active').length,'active'],['待报废',all.filter(e=>e.lifecycle==='pending_scrap').length,'scrap'],['待完善',all.filter(incomplete).length,'incomplete']];const wrap=$('ledger-stats');wrap.replaceChildren();for(const [name,val,dim] of cards){const col=document.createElement('div');col.className='col-6 col-md-3';const c=document.createElement('button');c.type='button';c.className='card stat-card w-100'+(isStatActive(dim)?' active':'');c.append(text('strong',String(val)),text('span',name));c.onclick=()=>toggleStat(dim);col.append(c);wrap.append(col);}}
 function toggleStat(dim){if(dim==='all')resetFilters();else if(dim==='active'){$('filter-life').value='active';incompleteOnly=false;}else if(dim==='scrap'){$('filter-life').value='pending_scrap';incompleteOnly=false;}else if(dim==='incomplete'){incompleteOnly=!incompleteOnly;if(incompleteOnly)$('filter-life').value='';}page=1;render();}
 function resetFilters(){for(const id of ['search','filter-life','filter-health','filter-criticality','filter-manufacturer'])$(id).value='';incompleteOnly=false;}
 function currentRecords(){const q=value('search').toLowerCase(),life=value('filter-life'),health=value('filter-health'),crit=value('filter-criticality'),mf=value('filter-manufacturer');return s.equipmentRecords.filter(e=>(e.name+e.code+e.location).toLowerCase().includes(q)&&(!life||life===e.lifecycle)&&(!health||healthOf(e)===health)&&(!crit||crit===e.criticality)&&(!mf||mf===e.manufacturer)&&(!incompleteOnly||incomplete(e)));}
 function renderHead(){const head=$('ledger-head');head.replaceChildren();const tr=document.createElement('tr');for(const c of baseCols){const th=document.createElement('th');th.textContent=c.label;th.scope='col';th.className='px-3 py-2 text-nowrap fw-semibold';tr.append(th);}for(const c of optCols){if(colOn[c.key]){const th=document.createElement('th');th.textContent=c.label;th.scope='col';th.className='px-3 py-2 text-nowrap fw-semibold';tr.append(th);}}const th=document.createElement('th');th.textContent='操作';th.scope='col';th.className='px-3 py-2 text-nowrap fw-semibold';tr.append(th);head.append(tr);}
 const csvEscape=v=>{const str=String(v??'');return /[",\n]/.test(str)?'"'+str.replace(/"/g,'""')+'"':str;};
 function exportCsv(){const cols=[...baseCols,...optCols.filter(c=>colOn[c.key])];const header=cols.map(c=>c.label);const rows=currentRecords().map(e=>cols.map(c=>cellFor(c.key,e).map(n=>n.textContent).join(' ')));const csv=[header.join(',')].concat(rows.map(r=>r.map(csvEscape).join(','))).join('\n');const blob=new Blob(['\ufeff'+csv],{type:'text/csv;charset=utf-8'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='设备台账.csv';a.click();URL.revokeObjectURL(a.href);Eam.message('已导出 '+rows.length+' 台设备');}
 function exportOne(e){const cols=[...baseCols,...optCols];const header=cols.map(c=>c.label);const row=cols.map(c=>cellFor(c.key,e).map(n=>n.textContent).join(' '));const csv=[header.join(',')].concat([row.map(csvEscape).join(',')]).join('\n');const blob=new Blob(['\ufeff'+csv],{type:'text/csv;charset=utf-8'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=(e.code||'device')+'.csv';a.click();URL.revokeObjectURL(a.href);Eam.message('已导出 '+e.name+' 档案');}
 document.addEventListener('click',e=>document.querySelectorAll('.ledger-more[open]').forEach(d=>{if(!d.contains(e.target))d.open=false;}));document.addEventListener('keydown',e=>{if(e.key==='Escape')document.querySelectorAll('.ledger-more[open]').forEach(d=>{d.open=false;d.querySelector('summary').focus();});});
 function render(){tree();renderHead();const records=currentRecords();renderStats();
  const pages=Math.max(1,Math.ceil(records.length/10));page=Math.min(page,pages);const list=$('equipment-list');list.replaceChildren();
  for(const e of records.slice((page-1)*10,page*10)){const row=document.createElement('tr');
   for(const c of [...baseCols,...optCols.filter(c=>colOn[c.key])])row.append(cell(c.label,...cellFor(c.key,e)));
   const actions=cell('操作',button('档案',()=>Eam.go('device',{equipment:e.id})),button('编辑',()=>open(e),can&&e.lifecycle!=='scrapped'));
   const more=document.createElement('details');more.className='ledger-more';const summary=document.createElement('summary');summary.className='btn btn-link btn-sm text-decoration-none text-nowrap';summary.textContent='更多';more.append(summary);const menu=document.createElement('div');menu.className='ledger-menu';more.append(menu);actions.append(more);
   menu.append(button('查看资料',()=>{more.open=false;open(e,true);}),button('结构与附件',()=>{more.open=false;openStructure(e);},true),button('复制建档',()=>{more.open=false;open({...e,id:null,revision:undefined,lifecycle:'draft'});}),button('导出档案',()=>{more.open=false;exportOne(e);}),button('履历直达',()=>{more.open=false;Eam.go('device',{equipment:e.id,tab:'history'});}));
   const next={draft:'active',active:'stopped',stopped:'active'}[e.lifecycle];if(next)menu.append(button(next==='active'?(e.lifecycle==='draft'?'验收启用':'恢复在用'):'停用',()=>confirmRun('变更为'+label[next],'equipmentLifecycle',{id:e.id,next}),can));if(['active','stopped'].includes(e.lifecycle))menu.append(button('申请报废',()=>confirmRun('转入待报废（模拟审核）','equipmentLifecycle',{id:e.id,next:'pending_scrap'}),can));if(e.lifecycle==='pending_scrap')menu.append(button('确认报废',()=>confirmRun('报废后档案只读','equipmentLifecycle',{id:e.id,next:'scrapped'}),can),button('退回停用',()=>confirmRun('报废退回','equipmentLifecycle',{id:e.id,next:'stopped'}),can));if(e.lifecycle==='draft')menu.append(button('删除草稿',()=>confirmRun('删除未启用草稿设备','deleteEquipment',{id:e.id}),can));const actionGroup=document.createElement('div');actionGroup.className='d-flex align-items-center flex-nowrap gap-1';while(actions.firstChild){const child=actions.firstChild;if(child.tagName==='BUTTON')child.className='btn btn-link btn-sm text-decoration-none text-nowrap';actionGroup.append(child);}actions.classList.add('text-nowrap');actions.append(actionGroup);row.append(actions);list.append(row);}
  put('equipment-count',EamUiComponents.paginationText(records.length,page,pages));$('empty-search').hidden=records.length>0;$('previous-page').disabled=page===1;$('next-page').disabled=page===pages;EamUiComponents.pagination($('equipment-count').parentElement,{page,pages,total:records.length,pageSize:10,countId:'equipment-count',previousId:'previous-page',nextId:'next-page',onChange:nextPage=>{page=nextPage;render();}});saveState();updateFilterBadge();EamUiComponents.decorateTables();
 }
 // 接入 Eam.Dialog.submitGuard（§7.4）：同步 preventDefault + busy 守卫 + 仅成功关闭；
 // 行为与原内联一致（保留 eq-* 取值与 revision 回传），失败保留输入。
 Eam.Dialog.submitGuard($('equipment-form'), async (fd, form) => {
   const payload = Object.fromEntries(fields.map(key => [key, value('eq-' + key)]));
   Object.assign(payload, { id: editing?.id, revision: editing?.revision, reason: value('eq-reason') });
   if (Eam.run('saveEquipment', payload)) {
     render();
     Eam.message('设备资料已保存');
     return true; // 成功 → 关闭弹窗
   } else {
     put('equipment-form-error', $('toast')?.textContent || '保存失败');
     return false; // 失败 → 保留输入，不关闭
   }
 });
 $('new-equipment').disabled=!can;$('new-equipment').onclick=()=>open(null);$('equipment-close').onclick=()=>$('equipment-dialog').close();
 for(const id of ['search','filter-life','filter-health','filter-criticality','filter-manufacturer'])$(id).addEventListener(id==='search'?'input':'change',()=>{page=1;render();});$('reset-filter').onclick=()=>{resetFilters();page=1;render();};$('previous-page').onclick=()=>{page--;render();};$('next-page').onclick=()=>{page++;render();};
 $('ledger-export').onclick=exportCsv;$('ledger-refresh').onclick=()=>{render();Eam.message('已刷新');};
 const colMenu=$('column-menu');$('ledger-columns').onclick=()=>{colMenu.hidden=!colMenu.hidden;$('ledger-columns').setAttribute('aria-expanded',String(!colMenu.hidden));};
 for(const c of optCols){const cb=$('col-'+c.key);if(cb)cb.addEventListener('change',e=>{colOn[c.key]=e.target.checked;render();});}
 document.addEventListener('click',e=>{if(!colMenu.hidden&&!colMenu.contains(e.target)&&e.target.id!=='ledger-columns'){colMenu.hidden=true;$('ledger-columns').setAttribute('aria-expanded','false');}});
 const resetPart=()=>{partId=null;for(const id of ['part-code','part-name'])$(id).value='';$('part-parent').value='';};
 function structures(){const eq=s.equipmentRecords.find(e=>e.id===structureId),editable=can&&eq.lifecycle!=='scrapped';put('structure-info',eq.code+' / '+eq.name);const parts=s.parts.filter(p=>p.equipmentId===structureId),select=$('part-parent');select.replaceChildren(new Option('根部位',''));for(const p of parts)select.add(new Option(p.name,p.id));const list=$('parts-list');list.replaceChildren();for(const p of parts){Eam.row(list,p.code+' / '+p.name,'父部位：'+(parts.find(x=>x.id===p.parentId)?.name||'根'));list.lastChild.append(button('编辑',()=>{partId=p.id;$('part-code').value=p.code;$('part-name').value=p.name;select.value=p.parentId;},editable),button('删除',()=>Eam.confirm('删除未引用部位',reason=>{if(!Eam.run('deletePart',{id:p.id,reason}))return false;structures();return true;}),editable));}if(!parts.length)Eam.row(list,'尚无维护部位','新增部位后可指定父部位');for(const id of ['part-save','part-reset'])$(id).disabled=!editable;}
 function openStructure(e){structureId=e.id;structures();resetPart();$('structure-dialog').showModal();}
 $('part-form').onsubmit=e=>{e.preventDefault();if(Eam.run('savePart',{id:partId,equipmentId:structureId,code:value('part-code'),name:value('part-name'),parentId:value('part-parent')})){structures();resetPart();}};$('part-reset').onclick=resetPart;
 $('open-device-resources').onclick=()=>Eam.go('device',{equipment:structureId,tab:'media'});$('structure-close').onclick=()=>$('structure-dialog').close();
 const afDialog=$('advanced-filter-dialog');
 $('open-advanced-filter').onclick=()=>EamUiComponents.openFilter(afDialog,$('open-advanced-filter'));

 function updateFilterBadge(){const n=[value('filter-life'),value('filter-health'),value('filter-criticality'),value('filter-manufacturer')].filter(Boolean).length;const badge=$('filter-badge');const btn=$('open-advanced-filter');if(n>0){badge.hidden=false;badge.textContent=String(n);btn.classList.add('active');put('af-hint','已应用 '+n+' 项筛选。');}else{badge.hidden=true;btn.classList.remove('active');put('af-hint','未应用筛选。');}}
 function tree(){const mount=$('dynamic-tree');mount.replaceChildren();const mode=treeMode;const icon=(kind)=>{const svg=document.createElementNS('http://www.w3.org/2000/svg','svg');svg.setAttribute('viewBox','0 0 24 24');svg.setAttribute('width','16');svg.setAttribute('height','16');svg.setAttribute('fill','none');svg.setAttribute('stroke','currentColor');svg.setAttribute('stroke-width','1.7');svg.setAttribute('aria-hidden','true');svg.classList.add('flex-shrink-0');const path=document.createElementNS(svg.namespaceURI,'path');path.setAttribute('d',kind==='folder'?'M3 6h7l2 2h9v12H3z':'M4 6h16v14H4z M8 6V3h8v3 M8 11h8 M8 15h5');svg.append(path);return svg;};
 const nodeButton=(name,code,onClick,selected)=>{const node=button('',onClick);node.className='btn btn-sm w-100 d-flex align-items-center gap-2 text-start '+(selected?'btn-primary':'btn-light');node.setAttribute('aria-pressed',String(selected));node.append(icon('device'));const caption=document.createElement('span');caption.className='text-truncate';caption.textContent=name;caption.title=name+(code?' · '+code:'');node.append(caption);return node;};
 const query=value('tree-search').trim().toLowerCase();const matches=(...values)=>!query||values.join(' ').toLowerCase().includes(query);const source=s.equipmentRecords.filter(e=>mode==='location'?matches(e.name,e.code,e.location):matches(e.name,e.code,...s.parts.filter(p=>p.equipmentId===e.id).flatMap(p=>[p.name,p.code])));
 const group=(label,key,count)=>{const details=document.createElement('details');details.className='mt-1';details.dataset.treeKey=key;details.open=!!query||treeExpanded.get(key)!==false;const summary=document.createElement('summary');summary.className='py-2 text-body-secondary small';summary.title=label;const line=document.createElement('span');line.className='d-inline-flex align-items-center gap-1';line.append(icon('folder'),text('span',label));if(count!==undefined){const badge=text('span',String(count));badge.className='badge text-bg-light border ms-1';line.append(badge);}summary.append(line);const children=document.createElement('div');children.className='ms-2 ps-2 border-start d-grid gap-1';details.append(summary,children);details.addEventListener('toggle',()=>treeExpanded.set(key,details.open));return {details,children};};
 const equipmentNode=e=>nodeButton(e.name,e.code,()=>{$('search').value=e.code;page=1;render();},value('search')===e.code);
 if(mode==='location'){const root={children:new Map(),devices:[]};for(const e of source){let branch=root;for(const part of (e.location||'未分配位置').split('/').filter(Boolean)){if(!branch.children.has(part))branch.children.set(part,{children:new Map(),devices:[]});branch=branch.children.get(part);}branch.devices.push(e);}const draw=(branch,target,prefix)=>{for(const [name,child]of branch.children){const key=prefix+'/'+name,g=group(name,key);draw(child,g.children,key);target.append(g.details);}for(const e of branch.devices)target.append(equipmentNode(e));};draw(root,mount,'location');}
 else for(const e of source){const g=group(e.name,'asset/'+e.id);g.children.append(equipmentNode(e));let parts=s.parts.filter(p=>p.equipmentId===e.id);if(query&&!matches(e.name,e.code)){const visible=new Set();for(const part of parts.filter(p=>matches(p.name,p.code))){let current=part;while(current&&!visible.has(current.id)){visible.add(current.id);current=parts.find(p=>p.id===current.parentId);}}parts=parts.filter(p=>visible.has(p.id));}const drawParts=(parent,target,visited)=>{for(const part of parts.filter(p=>p.parentId===parent||(!parent&&!parts.some(x=>x.id===p.parentId)))){if(visited.has(part.id))continue;const next=new Set(visited);next.add(part.id);const subgroup=group(part.name,'part/'+part.id);const caption=text('small',part.code);caption.className='text-body-secondary';subgroup.children.append(caption);drawParts(part.id,subgroup.children,next);target.append(subgroup.details);}};drawParts(null,g.children,new Set());mount.append(g.details);}if(!source.length){const empty=text('p',query?'没有匹配节点':'当前范围暂无设备');empty.className='text-body-secondary small py-3';mount.append(empty);}}

 for(const [id,expanded]of [['tree-expand-all',true],['tree-collapse-all',false]])$(id).onclick=()=>{for(const branch of $('dynamic-tree').querySelectorAll('details')){branch.open=expanded;treeExpanded.set(branch.dataset.treeKey,expanded);}};
 $('tree-search').addEventListener('input',tree);for(const mode of ['location','asset'])$('tree-'+mode).onclick=()=>{treeMode=mode;for(const value of ['location','asset']){const b=$('tree-'+value),selected=value===mode;b.classList.toggle('btn-primary',selected);b.classList.toggle('btn-outline-secondary',!selected);b.setAttribute('aria-pressed',String(selected));}tree();};
 const mfSel=$('filter-manufacturer');mfSel.replaceChildren(new Option('全部制造商',''));for(const m of [...new Set(s.equipmentRecords.map(e=>e.manufacturer).filter(Boolean))].sort())mfSel.add(new Option(m,m));
 loadState();render();const requested=new URLSearchParams(location.search).get('structure');if(requested){const record=s.equipmentRecords.find(e=>e.id===requested);if(record)openStructure(record);}
}

Eam.registerInit(initEquipment);
